<script setup lang="ts">
import {onMounted,reactive,ref} from 'vue'
import type {CuentaRubro,RubroCajaChica,RubroCajaChicaPayload} from '../interfaces/rubro-caja-chica.interface'
import {buscarCuentasRubroCajaChica,cambiarEstadoRubroCajaChica,guardarRubroCajaChica,listarRubrosCajaChica,obtenerRubroCajaChica} from '../services/rubro-caja-chica'
const rows=ref<RubroCajaChica[]>([]),accounts=ref<CuentaRubro[]>([]),search=ref(''),accountTerm=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const blank=():RubroCajaChicaPayload=>({codigo:'',detalle:'',cuenta_contable_id:null,movilidad:false,covid:false,activo:true}),form=reactive<RubroCajaChicaPayload>(blank()),message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.'
async function load(next=1){loading.value=true;error.value='';try{const r=await listarRubrosCajaChica(search.value,next);rows.value=r.data;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(e){error.value=message(e)}finally{loading.value=false}}
function create(){editing.value=null;Object.assign(form,blank());accounts.value=[];accountTerm.value='';modal.value=true}
async function edit(row:RubroCajaChica){loading.value=true;try{const x=await obtenerRubroCajaChica(row.id);editing.value=x.id;Object.assign(form,{codigo:x.codigo,detalle:x.detalle,cuenta_contable_id:x.cuenta_contable_id,movilidad:Boolean(x.movilidad),covid:Boolean(x.covid),activo:Boolean(x.activo)});accounts.value=x.cuenta_contable?[x.cuenta_contable]:[];accountTerm.value=x.cuenta_contable?.cta_contable??'';modal.value=true}catch(e){error.value=message(e)}finally{loading.value=false}}
async function findAccounts(){if(accountTerm.value.trim().length<4)return error.value='Ingrese al menos 4 caracteres para buscar la cuenta.';try{accounts.value=(await buscarCuentasRubroCajaChica(accountTerm.value.trim())).results}catch(e){error.value=message(e)}}
async function save(){if(!form.codigo.trim()||!form.detalle.trim())return error.value='Código y detalle son obligatorios.';loading.value=true;error.value='';try{await guardarRubroCajaChica(editing.value,{...form,codigo:form.codigo.trim().toUpperCase(),detalle:form.detalle.trim()});modal.value=false;success.value=`Rubro ${editing.value?'actualizado':'registrado'} correctamente.`;await load(page.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function toggle(row:RubroCajaChica){if(!confirm(`¿${row.activo?'Inactivar':'Activar'} el rubro ${row.codigo}?`))return;try{await cambiarEstadoRubroCajaChica(row.id);success.value='Estado actualizado correctamente.';await load(page.value)}catch(e){error.value=message(e)}}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Rubros de caja chica</nav><header class="hero"><b>RC</b><div><small>MIA · FINANZAS · CAJA CHICA</small><h1>Rubros de caja chica</h1><p>Clasificación contable de los gastos registrados en las rendiciones.</p></div><strong>{{total}} registros</strong><button @click="create">+ Nuevo rubro</button></header><p v-if="error" class="flash bad">{{error}}</p><p v-if="success" class="flash ok">{{success}}</p><form class="filters" @submit.prevent="load(1)"><input v-model.trim="search" placeholder="Buscar por código, detalle o cuenta contable"><button>Buscar</button><button type="button" class="soft" @click="search='';load(1)">Limpiar</button></form><section class="card"><div v-if="loading" class="empty">Procesando…</div><div v-else-if="!rows.length" class="empty">No se encontraron rubros.</div><div v-else class="grid"><article v-for="x in rows" :key="x.id" :class="{inactive:!x.activo}"><header><b>{{x.codigo}}</b><span :class="x.activo?'good':'off'">{{x.activo?'ACTIVO':'INACTIVO'}}</span></header><h3>{{x.detalle}}</h3><p><b>Cuenta:</b><br>{{x.cuenta_contable?x.cuenta_contable.cta_contable+' · '+x.cuenta_contable.descripcion:'Sin cuenta contable'}}</p><div class="tags"><i :class="{yes:x.movilidad}">Movilidad</i><i :class="{yes:x.covid}">COVID</i></div><footer><button class="edit" @click="edit(x)">Editar</button><button :class="x.activo?'danger':'enable'" @click="toggle(x)">{{x.activo?'Inactivar':'Activar'}}</button></footer></article></div><footer v-if="lastPage>1" class="pager"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><h2>{{editing?'Editar':'Registrar'}} rubro de caja chica</h2><button type="button" @click="modal=false">×</button></header><label>Código *<input v-model.trim="form.codigo" maxlength="10" required></label><label>Detalle *<input v-model.trim="form.detalle" maxlength="150" required></label><label>Buscar cuenta contable<span class="lookup"><input v-model.trim="accountTerm" placeholder="Código de cuenta (mínimo 4 caracteres)" @keyup.enter.prevent="findAccounts"><button type="button" @click="findAccounts">Buscar</button></span></label><label>Cuenta contable<select v-model.number="form.cuenta_contable_id"><option :value="null">Sin cuenta contable</option><option v-for="x in accounts" :key="x.id" :value="x.id">{{x.cta_contable}} · {{x.descripcion}}</option></select></label><fieldset><legend>Clasificación</legend><label><input v-model="form.movilidad" type="checkbox"> Movilidad</label><label><input v-model="form.covid" type="checkbox"> COVID</label></fieldset><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="loading">Guardar</button></footer></form></div></div></template>
<style scoped>.page{--a:#176d78;color:#344750}nav{margin-bottom:15px;color:#91a0a5;font-size:.68rem}nav a{color:var(--a)}.hero{display:flex;align-items:center;gap:14px;padding:20px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.hero>b{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a)}.hero>div{flex:1}.hero small{color:var(--a);font-size:.49rem}.hero h1{margin:3px 0;font-size:1.3rem}.hero p{margin:0;color:#7c8b91;font-size:.65rem}button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;cursor:pointer}.soft{color:#607078;background:#edf2f3}.flash{padding:10px}.bad{color:#9b3d48;background:#fdebee}.ok{color:#236c50;background:#e8f7ee}.filters{margin-top:11px;padding:13px;display:grid;grid-template-columns:1fr auto auto;gap:7px;background:#fff}input,select{box-sizing:border-box;width:100%;padding:9px;border:1px solid #d5dfe2;border-radius:6px;background:#fff}.card{margin-top:11px;background:#fff}.grid{padding:13px;display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.grid article{padding:14px;border:1px solid #dce5e7;border-top:4px solid var(--a);border-radius:8px}.grid article.inactive{opacity:.65}.grid article header,.grid article footer,.dialog header{display:flex;justify-content:space-between}.grid h3{font-size:.65rem}.grid p{min-height:42px;font-size:.5rem;line-height:1.5}.tags{margin:8px 0}.tags i{display:inline-block;margin-right:4px;padding:4px 7px;border-radius:10px;background:#f0f2f3;color:#9aa4a8;font-size:.42rem}.tags i.yes{color:#267153;background:#e5f7ec}.good,.off{padding:4px 8px;border-radius:10px;font-size:.42rem}.good{color:#267153;background:#e5f7ec}.off{color:#9d414a;background:#fdebed}.edit{background:#c98a24}.danger{background:#b74b54}.enable{background:#27875f}.empty{padding:50px;text-align:center}.pager{padding:12px;display:flex;justify-content:center;gap:8px}.backdrop{position:fixed;z-index:100;inset:0;display:grid;place-items:center;padding:20px;background:#172b3d88}.dialog{width:min(600px,100%);padding:20px;border-radius:12px;background:#fff}.dialog h2{margin:0 0 15px}.dialog header button{color:#66757b;background:none;font-size:1.2rem}.dialog>label{display:grid;gap:5px;margin:10px 0;font-size:.52rem;font-weight:700}.lookup{display:flex}.lookup input{flex:1}.lookup button{border-radius:0 6px 6px 0}.dialog fieldset{margin:15px 0;border:1px solid #d5dfe2}.dialog fieldset label{display:inline-flex;margin:8px}.dialog fieldset input{width:auto}.dialog>footer{display:flex;justify-content:center;gap:8px}@media(max-width:950px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.filters,.grid{grid-template-columns:1fr}.hero{flex-wrap:wrap}.hero>b{display:none}}</style>